<canvas id="c" width="224" height="288"></canvas>
<script>
'use strict';
/* =========================================================================
   GALAGA clone - single file. Sections:
   1. canvas / scaling      2. helpers       3. sprites (pixel data)
   4. audio (Web Audio)     5. input         6. game state + init
   7. update logic          8. rendering     9. fixed-timestep loop
   ========================================================================= */

/* ---------- 1. canvas & crisp scaling ---------- */
const W=224,H=288;
const canvas=document.getElementById('c');
const ctx=canvas.getContext('2d');
function resize(){
  const s=Math.max(1,Math.floor(Math.min((innerWidth-16)/W,(innerHeight-16)/H)));
  canvas.style.width=(W*s)+'px'; canvas.style.height=(H*s)+'px';
}
addEventListener('resize',resize); resize();

/* ---------- 2. helpers ---------- */
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const rand=(a,b)=>a+Math.random()*(b-a);
const pick=a=>a[(Math.random()*a.length)|0];
/* Catmull-Rom spline through waypoints p (array of [x,y]), t in [0,1] */
function crAt(p,t){
  t=clamp(t,0,0.9999);
  const n=p.length-1,i=Math.floor(t*n),u=t*n-i,u2=u*u,u3=u2*u;
  const a=p[Math.max(i-1,0)],b=p[i],c=p[i+1],d=p[Math.min(i+2,n)];
  return {
    x:0.5*(2*b[0]+(-a[0]+c[0])*u+(2*a[0]-5*b[0]+4*c[0]-d[0])*u2+(-a[0]+3*b[0]-3*c[0]+d[0])*u3),
    y:0.5*(2*b[1]+(-a[1]+c[1])*u+(2*a[1]-5*b[1]+4*c[1]-d[1])*u2+(-a[1]+3*b[1]-3*c[1]+d[1])*u3)
  };
}
function text(s,x,y,c,size,align){
  ctx.fillStyle=c; ctx.font=(size||8)+"px 'Courier New',monospace";
  ctx.textAlign=align||'left'; ctx.fillText(s,x,y); ctx.textAlign='left';
}

/* ---------- 3. sprites (pixel art as data) ---------- */
function makeSprite(rows,pal){
  const w=Math.max(...rows.map(r=>r.length));
  return {w,h:rows.length,data:rows.map(r=>r.padEnd(w,'.')),pal};
}
function drawSprite(s,x,y,flash){
  x=Math.round(x-s.w/2); y=Math.round(y-s.h/2);
  for(let j=0;j<s.h;j++){const row=s.data[j];
    for(let i=0;i<s.w;i++){const c=row[i]; if(c==='.')continue;
      ctx.fillStyle=flash?'#fff':s.pal[c]; ctx.fillRect(x+i,y+j,1,1);}}
}
const PAL_PLAYER ={W:'#ffffff',B:'#3aa0ff',C:'#a8dcff'};
const PAL_CAPTURE={W:'#ffb26b',B:'#ff3b3b',C:'#ff8a7a'};
const PAL_ZAKO   ={Y:'#ffd93b',B:'#2b6cff',W:'#ffffff'};
const PAL_GOEI   ={R:'#ff3b3b',W:'#ffffff',O:'#ff9a3b'};
const PAL_BOSS   ={G:'#2fd12f',W:'#ffffff',Y:'#ffd93b'};
const PAL_BOSSDAM={P:'#8a5cff',W:'#ffffff',Y:'#ffd93b'};

const sprPlayer=makeSprite([
'......W......','......W......','......W......','.....WCW.....','.....WCW.....',
'....W.W.W....','....WWWWW....','...WWWWW WW..'.replace(' ',''),'..W.WWWWW.W..','..W.WWWWW.W..',
'.WW.WWWWW.WW.','.W..WWWWW..W.','WW.WWWWWWW.WW','WW.WWWWWWW.WW'],PAL_PLAYER);
const sprCaptured=makeSprite(sprPlayer.data.map(r=>r),PAL_CAPTURE);

const sprZako=[makeSprite([
'YY........YY','YY.YYYYYY.YY','.YYBBBBBBYY.','..YBBBBBBY..','...BWBBWB...','....BBBB....','.....BB.....'],PAL_ZAKO),
makeSprite([
'............','YY........YY','.YYYYYYYYYY.','..YYBBBBYY..','...BWBBWB...','....BBBB....','.....BB.....'],PAL_ZAKO)];

const sprGoei=[makeSprite([
'RRR........RRR','RRRRR....RRRRR','RRRRRWWWWRRRRR','RRRWWRRRRWWRRR','.RRRWOOWWRRR..','..RRRWOOWWRR..','...RRRBBRRR...','.....RRRR.....','......RR......'],PAL_GOEI),
makeSprite([
'..............','RRR........RRR','RRRRRWWWWRRRRR','RRRWWRRRRWWRRR','.RRRWOOWWRRR..','..RRRWOOWWRR..','...RRRBBRRR...','.....RRRR.....','..............'],PAL_GOEI)];

const sprBoss=[makeSprite([
'..W........W..','..WW......WW..','...GGGGGGGG...','..GGGGGGGGGG..','.GGWGGGGGGWGG.','.GGGGYYYYGGGG.','..GGWGGGGWGG..','...GGGGGGGG...','....GG..GG....','...GG....GG...','..G........G..','.GG........GG.'],PAL_BOSS),
makeSprite([
'..W........W..','..WW......WW..','...GGGGGGGG...','..GGGGGGGGGG..','.GGWGGGGGGWGG.','.GGGGYYYYGGGG.','..GGWGGGGWGG..','...GGGGGGGG...','...GG....GG...','....GG..GG....','...G......G...','..GG......GG..'],PAL_BOSS)];
const sprBossDam=[makeSprite(sprBoss[0].data,PAL_BOSSDAM),makeSprite(sprBoss[1].data,PAL_BOSSDAM)];

const sprBoom=[makeSprite([
'....Y....','...YYY...','..YYWYY..','.YYWWWYY.','YYWWWWWYY','.YYWWWYY.','..YYWYY..','...YYY...','....Y....'],{Y:'#ffd93b',W:'#ffffff'}),
makeSprite([
'..R...R..','...R.R...','.R.RWR.R.','..RWWW R..'.replace(' ',''),'RWWWWWWR.','.RWWWWR..','..RWWR...','...RR....','....R....'],{R:'#ff5a3b',W:'#ffffff'}),
makeSprite([
'.........','..R...R..','.R.....R.','..R.W.R..','.R.W.W.R.','..R.W.R..','.R.....R.','..R...R..','.........'],{R:'#ff5a3b',W:'#ffffff'})];
const sprBoomBig=[makeSprite([
'.....B.....','..B..B..B..','.B.BYYYB.B.','..BYYYYYB..','.BYYYWYYYB.','BYYYWWWYYYB','.BYYYWYYYB.','..BYYYYYB..','.B.BYYYB.B.','..B..B..B..','.....B.....'],{B:'#3aa0ff',Y:'#ffd93b',W:'#ffffff'}),
makeSprite([
'..R..R..R..','.R.RRRR.R..','R.RYYYYYR.R','.RYYYYYYYR.','RYYYWOWYYYR','.RYYYYYYYR.','R.RYYYYYR.R','.R.RRRR.R..','..R..R..R..'],{R:'#ff5a3b',Y:'#ffd93b',W:'#ffffff',O:'#ff9a3b'}),
makeSprite([
'.R.......R.','..R.....R..','.R..Y..Y.R.','..R.Y.Y.R..','.R..Y..Y.R.','..R.....R..','.R.......R.'],{R:'#ff5a3b',Y:'#ffd93b'})];
const sprMini=makeSprite(['....W....','....W....','...WWW...','..W.W.W..','.WWWWWWW.','W..WWW..W','WW.WWW.WW'],PAL_PLAYER);

/* ---------- 4. audio (all synthesized) ---------- */
let AC=null,master=null,NOISEBUF=null,beamNodes=null;
function initAudio(){
  if(AC)return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=0.35; master.connect(AC.destination);
    NOISEBUF=AC.createBuffer(1,AC.sampleRate*0.6,AC.sampleRate);
    const d=NOISEBUF.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  }catch(e){}
}
function tone(f0,f1,dur,type,vol,delay){
  if(!AC||G.muted)return;
  const t=AC.currentTime+(delay||0);
  const o=AC.createOscillator(),g=AC.createGain();
  o.type=type; o.frequency.setValueAtTime(Math.max(f0,1),t);
  if(f1)o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+0.02);
}
function noiseSfx(dur,vol,delay,cut){
  if(!AC||G.muted)return;
  const t=AC.currentTime+(delay||0);
  const src=AC.createBufferSource(); src.buffer=NOISEBUF;
  const f=AC.createBiquadFilter(); f.type='lowpass'; f.frequency.value=cut||3000;
  const g=AC.createGain(); g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  src.connect(f); f.connect(g); g.connect(master); src.start(t); src.stop(t+dur+0.02);
}
const sfx={
  shoot(){tone(950,180,0.09,'square',0.16);},
  enemyDie(){noiseSfx(0.15,0.25,0,2500); tone(320,70,0.16,'square',0.1);},
  bossHit(){tone(190,150,0.09,'square',0.22); tone(150,120,0.09,'square',0.18,0.09);},
  playerDie(){noiseSfx(0.6,0.4,0,1800); tone(420,50,0.6,'sawtooth',0.15);},
  capture(){tone(700,120,0.55,'square',0.14); tone(500,90,0.55,'square',0.1,0.1);},
  dock(){tone(420,840,0.22,'square',0.16);},
  extra(){tone(660,660,0.1,'square',0.2); tone(990,990,0.12,'square',0.2,0.11);},
  stage(){[523,659,784,1046,784,1046].forEach((f,i)=>tone(f,f,0.13,'square',0.14,i*0.14));},
  challenge(){[392,523,659,880].forEach((f,i)=>tone(f,f,0.11,'square',0.14,i*0.12));},
  beamStart(){
    if(!AC||G.muted||beamNodes)return;
    const t=AC.currentTime;
    const o1=AC.createOscillator(),o2=AC.createOscillator(),g=AC.createGain();
    const lfo=AC.createOscillator(),lg=AC.createGain();
    o1.type='sawtooth'; o2.type='sawtooth';
    o1.frequency.value=210; o2.frequency.value=217;
    lfo.frequency.value=11; lg.gain.value=0.035;
    g.gain.setValueAtTime(0.05,t);
    lfo.connect(lg); lg.connect(g.gain);
    o1.connect(g); o2.connect(g); g.connect(master);
    o1.start(t); o2.start(t); lfo.start(t);
    beamNodes={o1,o2,lfo,g};
  },
  beamStop(){
    if(beamNodes){const n=beamNodes; beamNodes=null;
      try{n.g.gain.setTargetAtTime(0,AC.currentTime,0.05);}catch(e){}
      setTimeout(()=>{try{n.o1.stop();n.o2.stop();n.lfo.stop();}catch(e){}},200);}
  }
};

/* ---------- 5. input ---------- */
const keys={},pressed={};
addEventListener('keydown',e=>{
  initAudio();
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','Enter'].includes(e.code))e.preventDefault();
  if(!keys[e.code])pressed[e.code]=true;
  keys[e.code]=true;
});
addEventListener('keyup',e=>{keys[e.code]=false;});

/* ---------- 6. game state ---------- */
const G={
  state:'title', timer:0, paused:false, muted:false,
  stage:1, score:0, high:+(localStorage.getItem('galaga_high')||0),
  reserves:2, nextExtra:20000, fired:0, hits:0,
  shots:[], ebullets:[], enemies:[], booms:[], popups:[],
  player:{x:112,y:262,alive:false,dual:false,resp:0,inv:0,cap:null},
  ftime:0, diveT:3, shotCd:0,
  ch:{wave:0,timer:0,hits:0,bonus:0,waveKills:0,waveActive:false},
  perfect:false
};
const stars=[];
for(let i=0;i<70;i++)stars.push({x:Math.random()*W,y:Math.random()*H,
  v:10+Math.random()*55,c:pick(['#ffffff','#ffffff','#cfe4ff','#ffe9c8','#c8fff0']),
  tw:Math.random()*6.28,tws:1+Math.random()*4});

function isCh(n){return n%4===3;}           // challenging stages: 3,7,11,...
function saveHigh(){if(G.score>G.high){G.high=G.score;localStorage.setItem('galaga_high',G.high);}}

/* ----- starfield ----- */
function updateStars(dt){
  for(const s of stars){s.y+=s.v*dt; s.tw+=s.tws*dt;
    if(s.y>=H){s.y=0;s.x=Math.random()*W;}}
}

/* ----- formation geometry ----- */
function formationBreath(){
  const full=G.enemies.length>0&&G.enemies.every(e=>e.state==='formation');
  return full?1+0.07*Math.sin(G.ftime*1.1):1;
}
function formationSway(){
  const full=G.enemies.length>0&&G.enemies.every(e=>e.state==='formation');
  return Math.sin(G.ftime*(full?0.55:0.9))*(full?12:8);
}
function slotPos(e){
  const br=formationBreath(),sw=formationSway();
  const sp=e.type===0?16:20;
  const c=e.type===0?4.5:3.5;
  return {x:112+(e.col-c)*sp*br+sw, y:26+e.row*16};
}

/* ----- stage setup: 40 enemies fly in along curved paths in 5 groups of 8 ----- */
function mkEnemy(type,col,row){
  return {type,col,row,state:'wait',delay:0,path:null,t:0,dur:3.4,
    x:-40,y:-40,hp:type===2?2:1,frame:0,animT:Math.random(),
    captive:null,escorts:null,escortN:0,shootT:1,beamT:0,flash:0,ch:false};
}
function startGame(){
  G.stage=1;G.score=0;G.reserves=2;G.nextExtra=20000;G.fired=0;G.hits=0;
  startIntro();
}
function startIntro(){
  G.state='intro';G.timer=isCh(G.stage)?2.2:2.0;
  (isCh(G.stage)?sfx.challenge:sfx.stage)();
}
function playInit(){
  const E=[];
  for(let c=2;c<=5;c++)E.push(mkEnemy(2,c,0));          // 4 boss galaga
  for(let c=0;c<8;c++)E.push(mkEnemy(1,c,1));           // 8 goei row1
  for(let c=0;c<8;c++)E.push(mkEnemy(1,c,2));           // 8 goei row2
  for(let c=0;c<10;c++)E.push(mkEnemy(0,c,3));          // 10 zako row3
  for(let c=0;c<10;c++)E.push(mkEnemy(0,c,4));          // 10 zako row4
  const boss=E.filter(e=>e.type===2);
  const g1=E.filter(e=>e.type===1&&e.row===1&&e.col>=2&&e.col<=5);
  const g2=E.filter(e=>e.type===0&&e.row===3&&e.col<8);
  const g3=E.filter(e=>e.type===0&&e.row===3&&e.col>=8)
            .concat(E.filter(e=>e.type===0&&e.row===4&&e.col<6));
  const g4=E.filter(e=>e.type===0&&e.row===4&&e.col>=6)
            .concat(E.filter(e=>e.type===1&&e.row===2&&e.col>=2&&e.col<=5));
  const g5=E.filter(e=>e.type===1&&!(e.row===1&&e.col>=2&&e.col<=5)
            &&!(e.row===2&&e.col>=2&&e.col<=5));
  G.enemies=E;
  scheduleGroup(g1.concat(boss),0.4,'top');
  scheduleGroup(g2,2.6,'left');
  scheduleGroup(g3,4.8,'right');
  scheduleGroup(g4,7.0,'top2');
  scheduleGroup(g5,9.2,'low');
  G.ftime=0;G.diveT=3.5;
  G.player.x=112;G.player.alive=true;G.player.dual=false;G.player.resp=0;G.player.inv=1;G.player.cap=null;
  G.shots.length=0;G.ebullets.length=0;G.booms.length=0;G.popups.length=0;
}
function entryPath(kind,slot,i){
  const j=(i%4)*4-6;
  const P={
    top :[[112,-24],[112,50],[140,80],[160,115],[135,140],[105,120],[95,80],slot],
    top2:[[112,-24],[112,50],[84,80],[64,115],[89,140],[119,120],[129,80],slot],
    left:[[-24,120+j],[30,160+j],[90,140+j],[140,170+j],[100,205+j],[55,170+j],[60,90],slot],
    right:[[248,120-j],[194,160-j],[134,140-j],[84,170-j],[124,205-j],[169,170-j],[164,90],slot],
    low :[[-24,205+j],[40,225+j],[100,200+j],[150,225+j],[190,190+j],[190,120],[170,70],slot]
  }[kind];
  return P;
}
function scheduleGroup(list,at,kind){
  list.forEach((e,i)=>{e.state='wait';e.delay=at+i*0.28;e.kind=kind;});
}
/* ----- challenging stage init ----- */
function challengeInit(){
  G.enemies.length=0;G.shots.length=0;G.ebullets.length=0;G.booms.length=0;G.popups.length=0;
  G.ch={wave:0,timer:1.2,hits:0,bonus:0,waveKills:0,waveActive:false};
  G.perfect=false;
  G.player.x=112;G.player.alive=true;G.player.dual=false;G.player.resp=0;G.player.inv=1;G.player.cap=null;
}
function wavePath(k,i){
  const j=i*5;
  if(k%2===0)return [[-24,90+j],[40,120+j],[85,80+j],[130,130+j],[90,185+j],[45,150+j],[90,110+j],
                     [150,90+j],[210,70+j],[252,60+j]];
  return [[248,90+j],[184,120+j],[139,80+j],[94,130+j],[134,185+j],[179,150+j],[134,110+j],
          [74,90+j],[14,70+j],[-28,60+j]];
}
function spawnWave(){
  const k=G.ch.wave;
  const types=[2,1,0,0,0,0,1,2];
  types.forEach((t,i)=>{
    const e=mkEnemy(t,0,0); e.ch=true; e.state='wait'; e.delay=i*0.3;
    e.path=wavePath(k,i); e.dur=3.6; e.hp=1;
    G.enemies.push(e);
  });
  G.ch.waveKills=0;G.ch.waveActive=true;G.ch.wave++;
}

/* ---------- 7. update logic ---------- */
function update(dt){
  updateStars(dt);
  if(pressed.KeyM)G.muted=!G.muted;
  if(G.paused){
    if(pressed.KeyP)G.paused=false;
    pressed={};return;
  }
  if(pressed.KeyP&&(G.state==='play'||G.state==='challenge'))G.paused=true;
  switch(G.state){
    case 'title':if(pressed.Enter)startGame();break;
    case 'intro':G.timer-=dt;if(G.timer<=0){if(isCh(G.stage)){challengeInit();G.state='challenge';}else{playInit();G.state='play';}}break;
    case 'play':updatePlay(dt);break;
    case 'challenge':updateChallenge(dt);break;
    case 'challengeResult':G.timer-=dt;if(G.timer<=0){G.stage++;startIntro();}break;
    case 'clear':G.timer-=dt;if(G.timer<=0){G.stage++;startIntro();}break;
    case 'gameover':G.timer+=dt;if(G.timer>4){saveHigh();G.state='results';G.timer=0;}break;
    case 'results':G.timer+=dt;if(G.timer>6||pressed.Enter){G.state='title';}break;
  }
  pressed={};
}

/* ----- shared: explosions, popups, extra ships, ship loss ----- */
function boom(x,y,big){G.booms.push({x,y,t:0,big});}
function popup(x,y,txt,c){G.popups.push({x,y,txt,c,t:0});}
function addScore(n,x,y){
  G.score+=n; if(x!==undefined)popup(x,y,''+n,'#fff');
  while(G.score>=G.nextExtra){G.reserves++;G.nextExtra+=70000;sfx.extra();}
  if(G.score>G.high)G.high=G.score;
}
function loseShip(){
  if(G.reserves>0){G.reserves--;G.player.resp=2.2;}
  else{G.player.alive=false;sfx.beamStop();G.state='gameover';G.timer=0;}
}

/* ----- player firing / bullets ----- */
function firePlayer(){
  const P=G.player;
  if(P.dual){G.shots.push({x:P.x-8,y:P.y-8});G.shots.push({x:P.x+8,y:P.y-8});G.fired+=2;}
  else{G.shots.push({x:P.x,y:P.y-8});G.fired++;}
  G.hits===G.hits; // (hit counting happens on bullet impacts)
  sfx.shoot();
}
function updateBullets(dt){
  for(let i=G.shots.length-1;i>=0;i--){const b=G.shots[i];b.y-=6.5*dt*60/60*60*dt; }
  // (simple Euler step)
  for(const b of G.shots)b.y-=0; // placeholder removed below
}

/* ----- main play update ----- */
function updatePlay(dt){
  G.ftime+=dt;
  const P=G.player;

  /* captured-while-being-dragged animation */
  if(P.cap){
    P.cap.t+=dt;
    const s=slotPos(P.cap.boss),tx=s.x,ty=s.y-16;
    const u=clamp(P.cap.t/1.3,0,1),eu=u*u*(3-2*u);
    P.x=P.cap.sx+(tx-P.cap.sx)*eu; P.y=P.cap.sy+(ty-P.cap.sy)*eu;
    if(u>=1){P.cap.boss.captive={x:tx,y:ty,shootT:1};P.cap=null;loseShip();}
  }
  /* movement + fire */
  if(P.alive&&P.resp<=0){
    const dir=((keys.ArrowRight||keys.KeyD)?1:0)-((keys.ArrowLeft||keys.KeyA)?1:0);
    P.x=clamp(P.x+dir*140*dt,12,W-12);
    G.shotCd-=dt;
    if(keys.Space&&G.shots.length<2&&G.shotCd<=0){firePlayer();G.shotCd=0.18;}
  }
  if(!P.alive&&P.resp>0){P.resp-=dt;if(P.resp<=0){P.alive=true;P.x=112;P.dual=false;P.inv=1.2;}}
  if(P.inv>0)P.inv-=dt;

  /* player bullets */
  for(let i=G.shots.length-1;i>=0;i--){
    const b=G.shots[i];b.y-=330*dt;
    if(b.y<-6){G.shots.splice(i,1);continue;}
    let hit=false;
    for(const e of G.enemies){
      if(e.state==='dead'||e.ch&&false)continue;
      const hw=e.type===2?7:e.type===1?6:5, hh=e.type===2?6:5;
      if(Math.abs(b.x-e.x)<=hw&&Math.abs(b.y-e.y)<=hh){
        G.hits++; hit=true; e.flash=0.08; e.hp--;
        if(e.hp>0){sfx.bossHit();}
        else killEnemy(e,b.x,b.y,false);
        break;
      }
    }
    if(hit)G.shots.splice(i,1);
  }
  /* enemy bullets */
  for(let i=G.ebullets.length-1;i>=0;i--){
    const b=G.ebullets[i];b.y+=b.vy*dt*60;
    if(b.y>H+8){G.ebullets.splice(i,1);continue;}
    if(P.alive&&!P.cap&&P.resp<=0&&P.inv<=0){
      const halves=P.dual?[P.x-8,P.x+8]:[P.x];
      for(const hx of halves){
        if(Math.abs(b.x-hx)<5&&Math.abs(b.y-P.y)<7){
          G.ebullets.splice(i,1);
          if(P.dual){P.dual=false;boom(hx,P.y,false);sfx.enemyDie();P.inv=1.0;}
          else playerDeath();
          break;
        }
      }
    }
  }
  /* enemies */
  for(const e of G.enemies)updEnemy(e,dt);
  /* player <-> enemy collision (ramming destroys both, no points) */
  if(P.alive&&!P.cap&&P.resp<=0&&P.inv<=0){
    const halves=P.dual?[P.x-8,P.x+8]:[P.x];
    outer:
    for(const e of G.enemies){
      if(e.state==='dead'||e.state==='wait')continue;
      if(e.y<P.y-14||e.y>P.y+14)continue;
      for(const hx of halves){
        if(Math.abs(e.x-hx)<(e.type===2?11:10)&&Math.abs(e.y-P.y)<11){
          killEnemy(e,e.x,e.y,true);
          if(P.dual){P.dual=false;boom(hx,P.y,false);sfx.enemyDie();P.inv=1.0;}
          else playerDeath();
          break outer;
        }
      }
    }
  }
  /* dive scheduler (never while player is respawning/dead) */
  G.diveT-=dt;
  if(G.diveT<=0&&P.alive&&P.resp<=0&&!P.cap&&G.ftime>2.5){
    G.diveT=Math.max(0.8,3.4-G.stage*0.22)*rand(0.6,1.4);
    const inForm=G.enemies.filter(e=>e.state==='formation');
    if(inForm.length){
      const bosses=inForm.filter(e=>e.type===2);
      const e=(bosses.length&&Math.random()<0.55)?pick(bosses):pick(inForm);
      startDive(e);
    }
  }
  /* cleanup + stage clear */
  G.enemies=G.enemies.filter(e=>e.state!=='dead');
  if(G.enemies.length===0&&G.state==='play'){sfx.stage();G.state='clear';G.timer=2.5;}
  /* booms & popups */
  for(const b of G.booms)b.t+=dt;
  G.booms=G.booms.filter(b=>b.t<0.5);
  for(const p of G.popups){p.t+=dt;p.y-=14*dt;}
  G.popups=G.popups.filter(p=>p.t<0.7);
}
function playerDeath(){
  const P=G.player;P.alive=false;P.dual=false;
  boom(P.x,P.y,true);sfx.playerDie();sfx.beamStop();
  loseShip();
}

/* ----- enemy behaviour ----- */
function enemyShoot(e){
  if(G.ebullets.length>=10)return;
  G.ebullets.push({x:e.x,y:e.y+6,vy:2.2+G.stage*0.04});
}
function captiveShoot(c,x,y){
  if(G.ebullets.length>=10)return;
  const P=G.player;
  const dx=clamp(P.x-x,-60,60),dy=Math.max(P.y-y,10);
  const sp=2.4+G.stage*0.04;
  G.ebullets.push({x,y,vy:sp*dy/Math.hypot(dx,dy),vx:sp*dx/Math.hypot(dx,dy)});
}
function startReturn(e){
  const s=slotPos(e);
  e.path=[[e.x,e.y],[(e.x+s.x)/2+rand(-25,25),(e.y+s.y)/2],[s.x,s.y-20],[s.x,s.y]];
  e.t=0;e.dur=1.6;e.state='return';
}
function startDive(e){
  const P=G.player;
  const wantBeam=e.type===2&&!e.captive&&G.stage>=2&&Math.random()<0.5;
  /* escorts: boss dives with up to two nearby goei */
  if(e.type===2){
    const cand=G.enemies.filter(g=>g.type===1&&g.state==='formation'&&Math.abs(g.col-e.col)<=2);
    const n=cand.length?(Math.random()<0.55?(Math.random()<0.5?1:2):0):0;
    e.escorts=cand.slice(0,n);e.escortN=n;
  }
  if(wantBeam){
    const bx=clamp(P.x+rand(-25,25),36,W-36);
    e.path=[[e.x,e.y],[e.x+rand(-15,15),e.y+50],[(e.x+bx)/2,115],[bx,150]];
    e.t=0;e.dur=1.6;e.state='dive';e.beamAfter=true;e.shootT=0.4;
    return;
  }
  const tgt=clamp(P.x+rand(-50,50),20,W-20);
  const s1=e.x+(Math.random()<0.5?-1:1)*rand(15,35);
  e.path=[[e.x,e.y],[s1,e.y+35],[(s1+tgt)/2+rand(-20,20),e.y+95],[tgt,H+16]];
  e.t=0;e.dur=Math.max(1.3,2.4-G.stage*0.08);e.state='dive';e.beamAfter=false;e.shootT=rand(0.2,0.7);
}
function updEnemy(e,dt){
  if(e.flash>0)e.flash-=dt;
  e.animT+=dt;e.frame=(e.animT*8|0)&1;
  const s=slotPos(e);
  switch(e.state){
    case 'wait':
      e.delay-=dt;
      if(e.delay<=0){e.state='enter';e.t=0;
        e.path=e.ch?e.path:entryPath(e.kind,s,(e.col+e.row));}
      break;
    case 'enter':
      e.t+=dt/e.dur;
      if(e.t>=1){if(e.ch){e.state='dead';}else{e.state='formation';e.x=s.x;e.y=s.y;}}
      else{const p=crAt(e.path,e.t);e.x=p.x;e.y=p.y;
        if(!e.ch&&Math.random()<dt*0.06&&e.y>10&&e.y<H-60)enemyShoot(e);}
      break;
    case 'formation':e.x=s.x;e.y=s.y;
      if(e.captive){e.captive.x=s.x;e.captive.y=s.y-16;}
      break;
    case 'dive':
      e.t+=dt/e.dur;
      if(e.t>=1){
        if(e.beamAfter){e.state='beam';e.beamT=3.5;sfx.beamStart();}
        else{ /* exited bottom -> re-enter from top toward slot */
          e.path=[[e.x,-24],[e.x,40],[s.x+rand(-30,30),60],[s.x,s.y]];
          e.t=0;e.dur=2.0;e.state='return';}
      }else{
        const p=crAt(e.path,e.t);e.x=p.x;e.y=p.y;
        e.shootT-=dt;
        if(e.shootT<=0&&e.y>30&&e.y<H-40){enemyShoot(e);e.shootT=rand(0.6,1.3);}
        if(e.escorts)e.escorts.forEach((g,i)=>{g.state='escort';
          g.x=e.x+(i===0?-18:18);g.y=e.y+(i===0?18:30);});
        if(e.captive){e.captive.x=e.x;e.captive.y=e.y-16;
          e.captive.shootT-=dt;
          if(e.captive.shootT<=0&&e.y<H-60){captiveShoot(e.captive,e.captive.x,e.captive.y);e.captive.shootT=rand(0.9,1.5);}}
      }
      break;
    case 'return':
      e.t+=dt/e.dur;
      if(e.t>=1){e.state='formation';e.x=s.x;e.y=s.y;
        if(e.captive){e.captive.x=s.x;e.captive.y=s.y-16;}}
      else{const p=crAt(e.path,e.t);e.x=p.x;e.y=p.y;
        if(e.captive){e.captive.x=e.x;e.captive.y=e.y-16;}}
      break;
    case 'beam':{
      e.beamT-=dt;
      const P=G.player;
      if(P.alive&&!P.cap&&P.resp<=0&&P.inv<=0&&e.y+10<P.y){
        const hw=4+(P.y-(e.y+10))*0.155;
        if(Math.abs(P.x-e.x)<hw-2)startCapture(e);
      }
      if(e.beamT<=0||!beamNodes&&G.muted&&e.beamT<3.4){
        sfx.beamStop();
        e.path=[[e.x,e.y],[e.x,e.y-50],[s.x+rand(-20,20),40],[s.x,s.y]];
        e.t=0;e.dur=1.8;e.state='return';
      }
      break;}
    case 'escort':break; // position driven by boss
    case 'freed':{
      e.t+=dt/e.dur;
      const P=G.player;
      const tx=P.alive&&P.resp<=0?P.x:e.x+rand(-20,20);
      const ty=P.alive&&P.resp<=0?P.y:H+20;
      const u=clamp(e.t,0,1);
      e.x=e.sx+(tx-e.sx)*u; e.y=e.sy+(ty-e.sy)*u;
      if(u>=1){
