function killEnemy(e,x,y,ram){
  e.state='dead';
  boom(e.x,e.y,false);sfx.enemyDie();
  if(!ram){
    let pts;
    if(e.type===2){
      if(e.state==='dive'||e.state==='beam'){pts=[400,800,1600][clamp(e.escortN,0,2)];}
      else pts=150;
    }else if(e.type===1)pts=(e.state==='dive'||e.state==='beam')?160:80;
