  if(e.captive){
    const c=e.captive;e.captive=null;
    if(e.state==='dive'||e.state==='beam'){
      /* freed! flies down to dock with the player */
      c.state='freed';c.sx=c.x;c.sy=c.y;c.t=0;c.dur=1.2;c.hp=1;c.type=3;c.frame=0;c.escorts=null;c.captive=null;
